-- prisma/migrations/20261011090000_event_ownership/migration.sql
-- B1-01 Event Data Model.
-- 1. Text limits on events (D-023). Generated by the Prisma schema engine.
-- 2. Every event has at least one OWNER membership (D-022). Hand-written: Prisma cannot express
--    triggers and does not diff them, so later migrations keep them.

-- AlterTable
ALTER TABLE "events" ALTER COLUMN "name" SET DATA TYPE VARCHAR(120),
ALTER COLUMN "description" SET DATA TYPE VARCHAR(5000),
ALTER COLUMN "venue" SET DATA TYPE VARCHAR(200);

-- Stop here if existing data already breaks the rule: a trigger only checks future changes.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "events" e
    WHERE NOT EXISTS (
      SELECT 1 FROM "event_members" m WHERE m."eventId" = e."id" AND m."role" = 'OWNER'
    )
  ) THEN
    RAISE EXCEPTION 'Migration stopped: some events have no OWNER member. Add an OWNER to each event first.';
  END IF;
END $$;

-- CreateFunction (hand-written, D-022)
-- Checks one event. Runs at commit (deferred), so an event and its first OWNER membership can be
-- inserted in either order inside one transaction.
CREATE FUNCTION "eventops_check_event_has_owner"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  target_event uuid;
BEGIN
  IF TG_TABLE_NAME = 'events' THEN
    target_event := NEW."id";
  ELSE
    target_event := OLD."eventId";
  END IF;

  -- The event itself was deleted (memberships cascade with it): nothing to check.
  IF NOT EXISTS (SELECT 1 FROM "events" WHERE "id" = target_event) THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM "event_members"
    WHERE "eventId" = target_event AND "role" = 'OWNER'
  ) THEN
    -- The rule name leads the message: database drivers do not always pass CONSTRAINT through,
    -- and the app recognises this error by it.
    RAISE EXCEPTION 'events_must_have_owner: event % must have at least one OWNER member.',
      target_event
      USING ERRCODE = '23514', CONSTRAINT = 'events_must_have_owner';
  END IF;

  RETURN NULL;
END;
$$;

-- CreateTrigger (hand-written, D-022): a new event must get an OWNER in the same transaction.
CREATE CONSTRAINT TRIGGER "events_must_have_owner"
  AFTER INSERT ON "events"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "eventops_check_event_has_owner"();

-- CreateTrigger (hand-written, D-022): removing, demoting or moving the last OWNER fails.
CREATE CONSTRAINT TRIGGER "event_members_keep_owner"
  AFTER UPDATE OR DELETE ON "event_members"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "eventops_check_event_has_owner"();